// Rellena en unidades ya guardadas (localStorage) los campos nuevos que se agregaron
// después (p. ej. Seguros USA/MX) usando los datos semilla como referencia, sin pisar
// nada que el usuario ya haya capturado o editado.
const SEED_BACKFILL_FIELDS = [
  "seguroUsaAseguradora", "seguroUsaPoliza", "seguroUsaVencimiento", "seguroUsaRadioCobertura",
  "seguroMxAseguradora", "seguroMxPoliza", "seguroMxVencimiento",
  "irpVencimiento", "iftaVencimiento", "fumigacionVencimiento",
  "dobleEstiba", "thermo", "aptaProductosMedicos",
];
function backfillFromSeed(storedUnits) {
  const seedByEconomico = new Map(SEED_UNITS.map((s) => [s.numeroEconomico, s]));
  return storedUnits.map((u) => {
    const seed = seedByEconomico.get(u.numeroEconomico);
    if (!seed) return u;
    const patch = {};
    SEED_BACKFILL_FIELDS.forEach((k) => {
      if (!u[k] && seed[k]) patch[k] = seed[k];
    });
    return Object.keys(patch).length ? { ...u, ...patch } : u;
  });
}

